INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("リリ", 24001, 40011, 0, 321, 1, 1, 125801, 1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("クリア", 24001, 40011, 0, 322, 1, 2, 126001, 1, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("プレシア", 24001, 40011, 0, 323, 1, 3, 126101, 1, "んーと。\nこれ、あげる。\nはい", 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("リリ", 24001, 40011, 0, 324, 1, 4, 125801, 2, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("クリア", 24001, 40011, 0, 325, 1, 5, 126001, 2, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 2);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("プレシア", 24001, 40011, 0, 326, 1, 6, 126101, 2, "お兄。\nきてくれて、うれしい", 2);
